async function listJson(env,prefix){let all=[],cursor;do{const l=await env.BUCKET.list({prefix,cursor});for(const o of l.objects){const r=await env.BUCKET.get(o.key);if(r)all.push(await r.json());}cursor=l.truncated?l.cursor:undefined;}while(cursor);return all;}
async function partnerFor(env,uid){const code='BT38-'+(await digest(uid)).slice(0,20).toUpperCase();const r=await env.BUCKET.get('referrals/partners/'+code+'.json');return r?await r.json():null;}
async function resolveReferral(env,code){if(!env.BUCKET||!validCode(code))return null;const r=await env.BUCKET.get('referrals/partners/'+code+'.json');if(!r)return null;const partner=await r.json();const access=await partnerAccess(env.BUCKET,partner.owner);return partner.status==='active'&&access.active?{partner:{...partner,terms:modelTerms(access.terms,access.application.approved_model)}}:null;}
function publicTerms(s){return {enabled:!!s.enabled,version:s.version,commission_bps:s.commission_bps,hold_days:s.hold_days,payout_days:s.payout_days,operator:s.operator,contact:s.contact,scope:s.scope,models:s.models,eligible_basis:s.eligible_basis};}
async function referralApi(req,env,url){
 if(!env.BUCKET)return json({error:'Partner storage unavailable.'},503);
 const uid=req.headers.get('oai-authenticated-user-id'),email=req.headers.get('oai-authenticated-user-email');
 if(req.method!=='GET'&&req.headers.get('origin')!==url.origin)return json({error:'Invalid request origin.'},403);
 const s=await settings(env),path=url.pathname;
 if(!path.startsWith('/api/admin/')&&path!=='/api/referral/terms'&&(!uid||!(await partnerAccess(env.BUCKET,uid)).active))return json({error:'Approved partner access and accepted applicable terms are required.'},uid?403:401);
 if(path==='/api/referral/terms'&&req.method==='GET')return json(publicTerms(s));
 if(path.startsWith('/api/admin/referral')){
  if(!uid)return json({error:'Sign in to administer referrals.'},401);
  if(!ADMIN(req,env))return json({error:'Administrator access required.'},403);
  if(path==='/api/admin/referral-settings'&&req.method==='GET')return json(s);
  if(path==='/api/admin/referral-settings'&&req.method==='POST'){
   let d;try{d=await body(req);}catch{return json({error:'Invalid settings.'},400);}
   if(!validBasis(d))return json({error:'Define both alternative rates and the VAT, refund, third-party cost and partial-payment calculation basis before publishing.'},400);
   if(!Number.isInteger(d.commission_bps)||d.commission_bps<1||d.commission_bps>10000||!Number.isInteger(d.hold_days)||d.hold_days<0||d.hold_days>365||!Number.isInteger(d.payout_days)||d.payout_days<1||d.payout_days>365||typeof d.operator!=='string'||!d.operator.trim()||d.operator.length>300||typeof d.contact!=='string'||!/^https:\/\//.test(d.contact)||d.contact.length>500||typeof d.scope!=='string'||d.scope.length<20||d.scope.length>4000||d.confirmed!==true)return json({error:'Complete the percentage, payment periods, operator, contact URL and eligible scope; confirm the terms before saving.'},400);
   const next={enabled:d.enabled===true,models:{lead_introduction:500,full_sales:1000},eligible_basis:d.eligible_basis,commission_bps:500,hold_days:d.hold_days,payout_days:d.payout_days,operator:d.operator.trim(),contact:d.contact,scope:d.scope.trim(),version:crypto.randomUUID(),updated_at:new Date().toISOString(),updated_by:uid};
   await env.BUCKET.put('referrals/terms/'+next.version+'.json',JSON.stringify(next));await env.BUCKET.put(TERMS_KEY,JSON.stringify(next));return json(next);
  }
  if(path==='/api/admin/referral-ledger'&&req.method==='GET')return json({partners:await listJson(env,'referrals/partners/'),entries:await listJson(env,'referrals/ledger/')});
  if(path==='/api/admin/referral-receipt'&&req.method==='POST'){
   let d;try{d=await body(req);}catch{return json({error:'Invalid receipt.'},400);}
   if(!/^[a-f0-9-]{36}$/.test(d.enquiry_id||'')||typeof d.payment_reference!=='string'||!d.payment_reference.trim()||d.payment_reference.length>150||!Number.isSafeInteger(d.net_pence)||d.net_pence===0||Math.abs(d.net_pence)>100000000||!['payment','refund'].includes(d.type)||d.verified!==true||typeof d.note!=='string'||d.note.length>2000)return json({error:'Enter the enquiry ID, unique payment/refund reference, amount and verification note.'},400);
   if((d.type==='payment'&&d.net_pence<0)||(d.type==='refund'&&d.net_pence>0))return json({error:'Payments must be positive; refunds negative.'},400);
   const er=await env.BUCKET.get('records/enquiry/'+d.enquiry_id+'.json');if(!er)return json({error:'Enquiry not found.'},404);const enquiry=await er.json();if(!enquiry.referral)return json({error:'This enquiry has no recorded referral.'},400);if(!enquiry.referral.terms_version||!Number.isInteger(enquiry.referral.commission_bps)||!Number.isInteger(enquiry.referral.hold_days))return json({error:'Accepted commission terms must be recorded before an eligible receipt.'},409);
   const id=await digest(d.payment_reference.trim());const key='referrals/ledger/'+id+'.json';const old=await env.BUCKET.get(key);if(old){const entry=await old.json();if(entry.enquiry_id===d.enquiry_id&&entry.net_pence===d.net_pence&&entry.type===d.type)return json(entry);return json({error:'This transaction reference is already in use.'},409);}
   if(d.type==='refund'){if(typeof d.original_reference!=='string')return json({error:'Original payment reference required.'},400);const pr=await env.BUCKET.get('referrals/ledger/'+await digest(d.original_reference.trim())+'.json');if(!pr)return json({error:'Original verified payment not found.'},400);const payment=await pr.json();if(payment.type!=='payment'||payment.enquiry_id!==d.enquiry_id||Math.abs(d.net_pence)>payment.net_pence)return json({error:'Refund must match the original enquiry and not exceed its payment.'},400);const refunds=(await listJson(env,'referrals/ledger/')).filter(x=>x.type==='refund'&&x.original_reference===d.original_reference.trim());if(refunds.reduce((n,x)=>n+Math.abs(x.net_pence),0)+Math.abs(d.net_pence)>payment.net_pence)return json({error:'Recorded refunds would exceed the original payment.'},400);}
   const now=new Date(),commission=Math.sign(d.net_pence)*Math.round(Math.abs(d.net_pence)*enquiry.referral.commission_bps/10000);
   const entry={id,enquiry_id:enquiry.id,enquiry_reference:enquiry.reference,code:enquiry.referral.code,payment_reference:d.payment_reference.trim(),original_reference:d.original_reference?.trim()||null,type:d.type,commission_model:enquiry.referral.commission_model,commission_bps:enquiry.referral.commission_bps,net_pence:d.net_pence,commission_pence:commission,currency:'GBP',terms_version:enquiry.referral.terms_version,created_at:now.toISOString(),eligible_at:new Date(now.getTime()+enquiry.referral.hold_days*86400000).toISOString(),payout_days:enquiry.referral.payout_days,status:'recorded',verification:'admin_verified',note:d.note,recorded_by:uid};
   const put=await env.BUCKET.put(key,JSON.stringify(entry),{onlyIf:{etagDoesNotMatch:'*'}});if(put===null)return json({error:'Transaction reference already recorded; refresh the ledger.'},409);return json(entry);
  }
  if(path==='/api/admin/referral-paid'&&req.method==='POST')return json({error:'Use commission review: approval, completion, acceptance and clearance are required before a completed payout is recorded.'},409);
  return json({error:'Not found.'},404);
 }
 if(!uid||!email)return json({error:'Sign in to access your partner account.'},401);
 if(path==='/api/referral/account'&&req.method==='GET'){
  const partner=await partnerFor(env,uid);if(!partner)return json({partner:null,email,terms:publicTerms(s)});
  const enquiries=(await listJson(env,'records/enquiry/')).filter(x=>x.referral?.owner===uid).map(x=>({reference:x.reference,date:x.date,status:x.status}));
  const entries=(await listJson(env,'referrals/ledger/')).filter(x=>x.code===partner.code).map(({id,enquiry_reference,type,net_pence,commission_pence,currency,created_at,eligible_at,status,paid_at})=>({id,enquiry_reference,type,net_pence,commission_pence,currency,created_at,eligible_at,status,paid_at}));
  return json({partner:{name:partner.name,code:partner.code,terms:publicTerms(partner.terms),accepted_at:partner.accepted_at,status:partner.status},link:url.origin+'/r/'+partner.code,enquiries,entries,currentTerms:publicTerms(s)});
 }
 if(path==='/api/referral/register'&&req.method==='POST'){
  let d;try{d=await body(req);}catch{return json({error:'Invalid registration.'},400);}
  if(!s.enabled)return json({error:'Registration opens when commission terms are published.'},409);
  const access=await partnerAccess(env.BUCKET,uid);if(!access.active)return json({error:access.reason},403);if(d.accepted!==true||d.version!==s.version||typeof d.name!=='string'||!d.name.trim()||d.name.length>200)return json({error:'Read and accept the current terms and enter your name.'},400);
  const code='BT38-'+(await digest(uid)).slice(0,20).toUpperCase(),key='referrals/partners/'+code+'.json';const existing=await env.BUCKET.get(key);if(existing)return json({link:url.origin+'/r/'+code,code});
  const partner={code,owner:uid,email,name:d.name.trim(),status:'active',terms:modelTerms(s,access.application.approved_model),accepted_at:new Date().toISOString()};
  await env.BUCKET.put(key,JSON.stringify(partner),{onlyIf:{etagDoesNotMatch:'*'}});return json({link:url.origin+'/r/'+code,code});
 }
 return json({error:'Not found.'},404);
}

const REFERRAL_SCRIPT="(()=>{\n'use strict';\nconst $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));\nconst money=p=>new Intl.NumberFormat('en-GB',{style:'currency',currency:'GBP'}).format((p||0)/100);\nconst code=new URLSearchParams(location.search).get('ref');\nif(/^BT38-[A-F0-9]{20}$/.test(code||'')){document.querySelectorAll('a[href]').forEach(a=>{const u=new URL(a.href,location.href);if(u.origin===location.origin&&!['/admin','/partner','/referral-terms','/signin-with-chatgpt'].includes(u.pathname)){u.searchParams.set('ref',code);a.href=u.pathname+u.search+u.hash;}});const f=$('form[data-kind=\"enquiry\"]');if(f){const n=document.createElement('p');n.className='notice';n.textContent='Referral partner code: '+code+'. This code will be recorded with your enquiry.';f.prepend(n);}}\nasync function request(path,method='GET',data){const r=await fetch(path,{method,headers:{'Content-Type':'application/json'},...(data?{body:JSON.stringify(data)}:{})});const d=await r.json();if(!r.ok)throw Object.assign(Error(d.error||'Unable to complete request.'),{status:r.status});return d;}\nfunction terms(s){if(!s.enabled||!s.models||!s.eligible_basis)return '<p class=\"notice\">Programme activation requires published calculation, clearance and payment terms. Apply through Work With Us; only approved partners can activate referral access.</p>';return '<h3>BT38 partnership agreement</h3><p>Legal operator: '+esc(s.operator)+'.</p><p><strong>5% Lead Introduction Partner:</strong> introduce genuine qualified opportunities. BT38 experts handle discovery, technical discussions, quotations, negotiations and delivery.</p><p><strong>10% Full Sales Process Partner:</strong> manage the administrator-agreed commercial process through customer commitment. BT38 retains technical scope, authorised pricing, contractual approval and delivery unless separately agreed.</p><p>The rates are alternatives, not combined. Your administrator-approved model and accepted terms are snapshotted on each eligible referral. You cannot change historical rates.</p><p>Scope: '+esc(s.scope)+'</p>'+[['Eligible calculation','calculation'],['VAT','vat'],['Refunds','refunds'],['Third-party costs','third_party_costs'],['Partial payments','partial_payments']].map(([l,k])=>'<p><strong>'+l+':</strong> '+esc(s.eligible_basis[k])+'</p>').join('')+'<p>Commission is payable only after verified payment, project completion, customer acceptance and '+esc(s.hold_days)+' days of agreed clearance. Payment falls within '+esc(s.payout_days)+' days after eligibility is satisfied. Refunds, cancellations, attribution conflicts and disputes may reduce, reverse or delay commission.</p><p>No guaranteed sales or income. Do not invest your whole marketing budget. Start with your existing network. Approved partners receive product, customer, referral and dashboard guidance, without certification, paid advertising or unlimited coaching promises.</p><p>You may not bind BT38 to contracts, change pricing or promise unsupported features. Share only authorised customer details and accurate claims. You remain responsible for your taxes.</p><p>Contact: <a href=\"'+esc(s.contact)+'\">BT38</a>. Version '+esc(s.version)+'.</p>';}\nasync function partner(){const host=$('#affiliate-area');if(!host&&!$('#referral-terms'))return;const s=await request('/api/referral/terms');if($('#referral-terms'))$('#referral-terms').innerHTML=terms(s);if(!host)return;\ntry{const profileData=await request('/api/partner/profile');\nif(!profileData.profile||new URLSearchParams(location.search).has('edit')){\nconst p=profileData.profile||{};host.innerHTML='<h3>Your partner details</h3><p>Register your contact and business details. Your referral link and commission records belong to this signed-in account.</p><form id=\"partner-profile-form\"><div class=\"fields\">'+[['name','Your name',true],['company','Company / trading name',false],['country','Country',true],['phone','Telephone',false],['website','Website / professional profile',false],['specialism','Your services or referral network',false]].map(([k,l,required])=>'<label class=\"field\">'+l+(required?' *':'')+'<input name=\"'+k+'\" maxlength=\"500\" value=\"'+esc(p[k]||'')+'\" '+(required?'required':'')+'></label>').join('')+'</div><p class=\"notice\">Commission starts at 5% on eligible paid referrals. Bank and payment details are handled directly with Revolut and are not requested on this form.</p><p><a href=\"/privacy\">Privacy information ↗</a></p><button class=\"btn primary\">Save partner profile ↗</button><p id=\"partner-profile-result\" role=\"status\"></p></form>';\n$('#partner-profile-form').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;try{await request('/api/partner/profile','POST',Object.fromEntries(new FormData(e.target)));location.assign('/partner');}catch(err){$('#partner-profile-result').textContent=err.message;b.disabled=false;}};return;}\nconst d=await request('/api/referral/account');if(d.partner){host.innerHTML='<h3>Your referral link</h3><label class=\"field\">Share this link<input readonly id=\"share-link\" value=\"'+esc(d.link)+'\"></label><div class=\"actions\"><button class=\"btn primary\" id=\"copy-link\">Copy link</button><a class=\"btn\" href=\"/partner\">Open partner area</a></div><p id=\"copy-result\" role=\"status\"></p><p class=\"muted\">'+esc(d.partner.terms.commission_bps/100)+'% under accepted terms '+esc(d.partner.terms.version)+'.</p><h3>Recorded enquiries</h3>'+(d.enquiries.length?'<ul class=\"list\">'+d.enquiries.map(x=>'<li>'+esc(x.reference)+' · '+esc(x.status)+'</li>').join('')+'</ul>':'<p class=\"muted\">No referrals recorded yet. Share your link; an enquiry must include the code.</p>')+'<h3>Commission record</h3>'+(d.entries.length?'<ul class=\"list\">'+d.entries.map(x=>'<li>'+esc(x.enquiry_reference)+' · '+esc(x.type)+' · '+money(x.commission_pence)+' · '+esc(x.status)+' · eligible '+esc(new Date(x.eligible_at).toLocaleDateString('en-GB'))+'</li>').join('')+'</ul>':'<p class=\"muted\">No verified payment entries yet. An enquiry is not a sale or an earned commission.</p>')+'<p class=\"notice\">Payments and refunds are verified and recorded by BT38 administration. Verified checkout payments are recorded automatically when online payments are enabled. Other receipts and refunds are recorded by BT38 administration. Customer contact details are not disclosed in your partner area.</p>';\n$('#copy-link').onclick=async()=>{try{await navigator.clipboard.writeText(d.link);$('#copy-result').textContent='Link copied.';}catch{$('#share-link').select();$('#copy-result').textContent='Select and copy the link above.';}};return;}\nif(!s.enabled){host.innerHTML='<h3>Your partner profile is saved</h3><p>Your account is ready for the referral programme. Your unique link will activate once the full commission and payout terms are published and accepted.</p>'+terms(s)+'<a class=\"btn\" href=\"/partner?edit=1\">Edit partner profile ↗</a>';return;}host.innerHTML=terms(s)+'<form id=\"referral-register\"><label class=\"field\">Your name<input name=\"name\" required maxlength=\"200\" autocomplete=\"name\"></label><p class=\"muted\">Account email: '+esc(d.email)+'</p><label class=\"consent\"><input type=\"checkbox\" name=\"accepted\" required> I have read and accept these referral terms and the <a href=\"/privacy\">privacy information</a>.</label><button class=\"btn primary\" type=\"submit\">Register & get my referral link ↗</button><p id=\"register-result\" role=\"status\"></p></form>';\n$('#referral-register').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;try{await request('/api/referral/register','POST',{name:new FormData(e.target).get('name'),accepted:true,version:s.version});await partner();}catch(err){$('#register-result').textContent=err.message;b.disabled=false;}};\n}catch(e){host.innerHTML=e.status===401?terms(s)+'<p><a class=\"btn primary\" target=\"_top\" href=\"/auth/google?returnTo=%2Fpartner\">Sign in to register or view your link ↗</a></p><p class=\"muted\">Your partner account is private. Sign in with Google to identify your account.</p>':'<p class=\"message error\">'+esc(e.message)+'</p>';}}\nasync function admin(){const host=$('#referral-admin');if(!host)return;try{const s=await request('/api/admin/referral-settings');host.innerHTML='<h2>Referral programme</h2><p class=\"notice\">Registration remains closed until you enter and confirm your commercial terms. The controls below create actual commitments; use the agreed rate and payment schedule.</p><form id=\"referral-settings\"><p>Alternative administrator-assigned models: 5% lead introduction or 10% full commercial sales process. They are never combined.</p><div class=\"fields\"><label class=\"field\">Lead model reference rate (%)<input name=\"rate\" readonly type=\"number\" min=\"0.01\" max=\"100\" step=\"0.01\" required value=\"'+esc(s.commission_bps?s.commission_bps/100:'')+'\"></label><label class=\"field\">Hold after verified payment (days)<input name=\"hold\" type=\"number\" min=\"0\" max=\"365\" required value=\"'+esc(s.hold_days??'')+'\"></label><label class=\"field\">Pay within days after hold<input name=\"payout\" type=\"number\" min=\"1\" max=\"365\" required value=\"'+esc(s.payout_days??'')+'\"></label><label class=\"field\">Legal operator name<input name=\"operator\" maxlength=\"300\" required value=\"'+esc(s.operator||'')+'\"></label><label class=\"field full\">Contact URL<input name=\"contact\" type=\"url\" required value=\"'+esc(s.contact||location.origin+'/contact')+'\"></label><label class=\"field full\">Precisely which work earns commission<textarea name=\"scope\" required minlength=\"20\" maxlength=\"4000\">'+esc(s.scope||'')+'</textarea></label>'+[['calculation','Eligible project calculation basis'],['vat','VAT treatment'],['refunds','Refund and cancellation treatment'],['third_party_costs','Third-party cost treatment'],['partial_payments','Partial payment allocation']].map(([k,l])=>'<label class=\"field full\">'+l+'<textarea name=\"basis_'+k+'\" required minlength=\"10\" maxlength=\"2000\">'+esc(s.eligible_basis?.[k]||'')+'</textarea></label>').join('')+'</div><label class=\"consent\"><input type=\"checkbox\" name=\"enabled\" '+(s.enabled?'checked':'')+'> Open referral registration</label><details><summary>Review programme terms</summary>'+terms({...s,enabled:true,operator:s.operator||'[operator]',commission_bps:s.commission_bps||0,scope:s.scope||'[eligible scope]',hold_days:s.hold_days??'[hold]',payout_days:s.payout_days??'[payout]',contact:s.contact||'/contact'})+'</details><label class=\"consent\"><input name=\"confirmed\" type=\"checkbox\" required> I confirm the percentage, eligible scope and displayed referral terms for this business.</label><button class=\"btn primary\">Save versioned terms</button><p id=\"settings-result\" role=\"status\"></p></form><div class=\"divider\"></div><h3>Verified customer receipts</h3><p class=\"muted\">Record only confirmed eligible net receipts, after VAT and pass-through costs. Use a unique provider transaction reference. This does not take payment or send a payout.</p><form id=\"receipt-form\"><div class=\"fields\"><label class=\"field\">Enquiry UUID<input name=\"enquiry_id\" required></label><label class=\"field\">Unique transaction reference<input name=\"payment_reference\" required maxlength=\"150\"></label><label class=\"field\">Type<select name=\"type\"><option value=\"payment\">Payment</option><option value=\"refund\">Refund / chargeback</option></select></label><label class=\"field\">Net eligible amount (GBP; negative for refund)<input name=\"amount\" type=\"number\" step=\"0.01\" required></label><label class=\"field\">Original transaction reference (refund only)<input name=\"original_reference\" maxlength=\"150\"></label><label class=\"field full\">Verification / eligibility note<textarea name=\"note\" required maxlength=\"2000\"></textarea></label></div><label class=\"consent\"><input name=\"verified\" type=\"checkbox\" required> I verified the settled payment or refund and its eligibility against the accepted terms.</label><button class=\"btn primary\">Record verified receipt</button><p id=\"receipt-result\" role=\"status\"></p></form><div id=\"ledger-list\"></div>';\n$('#referral-settings').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);try{await request('/api/admin/referral-settings','POST',{models:{lead_introduction:500,full_sales:1000},eligible_basis:Object.fromEntries(['calculation','vat','refunds','third_party_costs','partial_payments'].map(k=>[k,f.get('basis_'+k)])),commission_bps:500,hold_days:Number(f.get('hold')),payout_days:Number(f.get('payout')),operator:f.get('operator'),contact:f.get('contact'),scope:f.get('scope'),enabled:f.has('enabled'),confirmed:f.has('confirmed')});$('#settings-result').textContent='Terms saved. New registrations use this version.';}catch(err){$('#settings-result').textContent=err.message;}};\n$('#receipt-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);try{const d=await request('/api/admin/referral-receipt','POST',{enquiry_id:f.get('enquiry_id'),payment_reference:f.get('payment_reference'),type:f.get('type'),net_pence:Math.round(Number(f.get('amount'))*100),original_reference:f.get('original_reference'),note:f.get('note'),verified:f.has('verified')});$('#receipt-result').textContent='Recorded '+money(d.commission_pence)+' commission. No money was sent.';await ledger();}catch(err){$('#receipt-result').textContent=err.message;}};await ledger();\n}catch(e){host.innerHTML='<p class=\"notice\">'+esc(e.message)+'</p>';}}\nasync function ledger(){const d=await request('/api/admin/referral-ledger');$('#ledger-list').innerHTML='<h3>Registered partners ('+d.partners.length+')</h3>'+d.partners.map(p=>'<p>'+esc(p.name)+' · '+esc(p.email)+' · '+esc(p.code)+'</p>').join('')+'<h3>Commission entries</h3>'+d.entries.map(x=>'<div class=\"record\">'+esc(x.enquiry_reference)+' · '+esc(x.payment_reference)+' · '+money(x.commission_pence)+' · '+esc(x.status)+(x.type==='payment'&&x.status!=='paid'?'<p><button class=\"btn mark-paid\" data-id=\"'+esc(x.id)+'\">Record completed payout</button></p>':'')+'</div>').join('');document.querySelectorAll('.mark-paid').forEach(b=>b.onclick=async()=>{const ref=prompt('Enter the bank/provider reference for the payout already completed:');if(!ref)return;try{await request('/api/admin/referral-paid','POST',{id:b.dataset.id,payout_reference:ref});await ledger();}catch(e){alert(e.message);}});}\npartner().catch(e=>{const x=$('#affiliate-area')||$('#referral-terms');if(x)x.textContent=e.message;});admin();\n})();\n";

