const CHECKOUT_PRODUCTS={"system": {"name": "Global ecommerce system", "amount": 499900, "detail": "White-label, self-hosted starting package. Includes training and three months of support. Source code excluded."}, "support": {"name": "Customer support", "amount": 9900, "detail": "One month of support for faults or issues with your existing delivered system, purchased as needed. No automatic renewal. Bespoke development is quoted separately."}, "audit": {"name": "Business Systems Audit", "amount": 9900, "detail": "A one-off review of existing business processes and systems, with recommendations for workflow and integration improvements."}};
const ce=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const gbp=p=>new Intl.NumberFormat('en-GB',{style:'currency',currency:'GBP'}).format(p/100);
function checkoutConfig(env){let tax;try{tax=JSON.parse(env.BILLING_COUNTRY_TAX_JSON||'{}');}catch{tax={};}const ready=env.CHECKOUT_ENABLED==='true'&&env.REVOLUT_PRODUCTION_API_SECRET_KEY&&env.REVOLUT_MERCHANT_API_VERSION&&env.REVOLUT_WEBHOOK_SIGNING_SECRET&&env.INVOICE_SELLER_NAME&&env.INVOICE_SELLER_ADDRESS&&env.INVOICE_CONTACT_EMAIL&&env.INVOICE_COMPANY_NUMBER&&Object.keys(tax).length;return {ready:!!ready,tax};}
const checkoutGet=async(env,key)=>{const r=await env.BUCKET.get(key);return r?await r.json():null;};
async function merchant(env,path,method='GET',payload,id){const host=env.REVOLUT_SANDBOX==='true'?'https://sandbox-merchant.revolut.com':'https://merchant.revolut.com';const r=await fetch(host+'/api/'+path,{method,headers:{Authorization:'Bearer '+env.REVOLUT_PRODUCTION_API_SECRET_KEY,'Revolut-Api-Version':env.REVOLUT_MERCHANT_API_VERSION,'Content-Type':'application/json',...(id?{'Idempotency-Key':id}:{})},...(payload?{body:JSON.stringify(payload)}:{}),signal:AbortSignal.timeout(20000)});if(!r.ok)throw Error('Payment provider unavailable. No payment has been confirmed.');return r.json();}
function invoiceHtml(i){return '<!doctype html><html lang="en"><meta charset="utf-8"><title>Invoice '+ce(i.number)+'</title><body style="font:16px Arial,sans-serif;color:#15223a;max-width:760px;margin:40px auto;padding:24px"><h1>BT38 · Invoice</h1><p><strong>PAID</strong> · '+ce(i.number)+'</p><p>Invoice date: '+ce(i.date)+'<br>Supply/payment date: '+ce(i.date)+'</p><h2>From</h2><p>'+ce(i.seller.name)+'<br>'+ce(i.seller.address).replace(/\n/g,'<br>')+'<br>'+ce(i.seller.email)+'<br>Company number: '+ce(i.seller.company_number)+(i.seller.vat_number?'<br>VAT number: '+ce(i.seller.vat_number):'')+'</p><h2>Bill to</h2><p>'+ce(i.customer.company)+'<br>'+ce(i.customer.name)+'<br>'+ce(i.customer.address)+'<br>'+ce(i.customer.city)+' '+ce(i.customer.postcode)+'<br>'+ce(i.customer.country)+(i.customer.vat_number?'<br>Customer VAT: '+ce(i.customer.vat_number):'')+'</p><h2>'+ce(i.product.name)+'</h2><p>'+ce(i.product.detail)+'</p><p>Quantity: 1<br>Net: '+gbp(i.net)+'<br>Tax ('+(i.tax_bps/100)+'%): '+gbp(i.tax)+'<br><strong>Total paid: '+gbp(i.amount)+'</strong><br>Balance due: £0.00</p><p>'+ce(i.tax_label)+'</p><p>Paid through Revolut. Payment reference: '+ce(i.provider_id)+'</p></body></html>';}
async function issueInvoice(env,order,payment){
 if(payment.id!==order.provider_id||payment.state!=='completed'||payment.amount!==order.amount||payment.currency!=='GBP'||Number(payment.outstanding_amount||0)!==0)throw Error('Payment details do not match this order.');
 const key='checkout/invoices/'+order.id+'.json';let invoice=await checkoutGet(env,key);
 if(!invoice){const date=new Date().toISOString().slice(0,10),net=Math.round(order.amount*10000/(10000+order.tax_bps));invoice={created_at:new Date().toISOString(),number:'BT38-'+order.id.replaceAll('-','').toUpperCase(),date,provider_id:order.provider_id,customer:order.customer,seller:order.seller,product:order.product,amount:order.amount,net,tax:order.amount-net,tax_bps:order.tax_bps,tax_label:order.tax_label,email_state:'pending'};await env.BUCKET.put(key,JSON.stringify(invoice),{onlyIf:{etagDoesNotMatch:'*'}});invoice=await checkoutGet(env,key);}
 // A paid checkout enters the same governed referral ledger as other customer receipts.
 if(order.referral){const terms=order.referral.terms,ledgerId=await digest(order.provider_id),ledgerKey='referrals/ledger/'+ledgerId+'.json';const entry={id:ledgerId,enquiry_id:order.enquiry_id||order.id,enquiry_reference:(order.enquiry_id?(await checkoutGet(env,'records/enquiry/'+order.enquiry_id+'.json'))?.reference:null)||'BT38-E-'+order.id.replaceAll('-','').slice(0,12).toUpperCase(),code:order.referral.code,payment_reference:order.provider_id,type:'payment',commission_model:terms.commission_model,commission_bps:terms.commission_bps,net_pence:invoice.net,commission_pence:Math.round(invoice.net*terms.commission_bps/10000),currency:'GBP',terms_version:terms.version,created_at:invoice.created_at,eligible_at:new Date(Date.parse(invoice.created_at)+terms.hold_days*86400000).toISOString(),payout_days:terms.payout_days,status:'recorded',verified_by:'revolut_completed_order',note:'Exact order verified against the payment provider'};await env.BUCKET.put(ledgerKey,JSON.stringify(entry),{onlyIf:{etagDoesNotMatch:'*'}});}
 if(!env.RESEND_API_KEY||!env.EMAIL_FROM){if(invoice.email_state!=='sent'){invoice.email_state='not_configured';await env.BUCKET.put(key,JSON.stringify(invoice));}return invoice;}
 if(invoice.email_state!=='sent'){
 const r=await fetch('https://api.resend.com/emails',{method:'POST',headers:{Authorization:'Bearer '+env.RESEND_API_KEY,'Content-Type':'application/json','Idempotency-Key':'invoice-'+order.id},body:JSON.stringify({from:env.EMAIL_FROM,to:[order.customer.email],subject:'Your paid BT38 invoice — '+invoice.number,html:invoiceHtml(invoice)}),signal:AbortSignal.timeout(20000)});
 if(!r.ok)throw Error('Payment confirmed; invoice email is awaiting delivery.');const sent=await r.json();if(!sent.id)throw Error('Invoice email confirmation is unavailable.');invoice.email_state='sent';invoice.email_id=sent.id;await env.BUCKET.put(key,JSON.stringify(invoice));}
 return invoice;
}
async function verifyCheckoutWebhook(req,env,raw){const ts=req.headers.get('Revolut-Request-Timestamp')||'',sig=req.headers.get('Revolut-Signature')||'';if(!/^\d+$/.test(ts)||Math.abs(Date.now()-Number(ts))>300000||!env.REVOLUT_WEBHOOK_SIGNING_SECRET)return false;const key=await crypto.subtle.importKey('raw',new TextEncoder().encode(env.REVOLUT_WEBHOOK_SIGNING_SECRET),{name:'HMAC',hash:'SHA-256'},false,['verify']);for(const part of sig.split(',')){const m=/^v1=([a-f0-9]{64})$/.exec(part.trim());if(m&&await crypto.subtle.verify('HMAC',key,Uint8Array.from(m[1].match(/../g),x=>parseInt(x,16)),new TextEncoder().encode('v1.'+ts+'.'+raw)))return true;}return false;}
async function checkoutApi(req,env,url){
 if(!env.BUCKET)return json({error:'Checkout is temporarily unavailable.'},503);
 const path=url.pathname,config=checkoutConfig(env);
 if(path==='/api/checkout/config'&&req.method==='GET')return json({ready:config.ready,products:OFFERS,countries:config.ready?Object.keys(config.tax):[],message:config.ready?'':'Online payment is not available yet. Please contact BT38 to arrange your purchase.'});
 if(path==='/api/checkout/webhook'&&req.method==='POST'){
 const raw=await req.text();if(raw.length>30000||!await verifyCheckoutWebhook(req,env,raw))return json({error:'Invalid signature.'},401);let event;try{event=JSON.parse(raw);}catch{return json({error:'Invalid event.'},400);}if(event.event!=='ORDER_COMPLETED')return json({ok:true});if(!/^[a-f0-9-]{36}$/.test(event.order_id||''))return json({error:'Invalid order.'},400);
 const link=await checkoutGet(env,'checkout/provider/'+event.order_id+'.json');if(!link)return json({ok:true});const order=await checkoutGet(env,'checkout/orders/'+link.id+'.json');if(!order)return json({error:'Order unavailable; retry.'},503);
 try{const payment=await merchant(env,'orders/'+order.provider_id);await issueInvoice(env,order,payment);return json({ok:true});}catch{return json({error:'Payment or invoice verification pending; retry.'},503);}}
 if(req.method==='POST'&&req.headers.get('origin')!==url.origin)return json({error:'Invalid request origin.'},403);
 if(path==='/api/checkout/create'&&req.method==='POST'){
 if(!config.ready)return json({error:'Online payment is not available yet. Please contact BT38 to arrange your purchase.'},503);
 const uid=req.headers.get('oai-authenticated-user-id');if(!uid)return json({error:'Please sign in before checkout.',signin:true},401);const account=await checkoutGet(env,'customers/accounts/'+await digest(uid)+'.json');if(!account)return json({error:'Complete your company profile before checkout.',signup:true},409);
 let d;try{d=await body(req);}catch{return json({error:'Invalid company details.'},400);}
 let offer;try{offer=await checkoutOffer(env.BUCKET,{product:d.product,enquiry:d.enquiry_id,quote:d.quote_id,user:uid});}catch(e){return json({error:e.message},e.status||400);}if(offer.product.self_hosted&&d.hosting_acknowledged!==true)return json({error:'Acknowledge the applicable hosting responsibilities before purchase.'},400);
 if(!offer.product||!/^([a-f0-9]{8}-[a-f0-9]{4}-4[a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12})$/.test(d.id||'')||!/^[a-f0-9]{64}$/.test(d.token||''))return json({error:'Invalid checkout request.'},400);
 const required=['company','name','email','address','city','postcode','country'];let customer={};for(const k of [...required,'phone','company_number','vat_number']){const v=d[k]??'';if(typeof v!=='string'||v.length>500||(required.includes(k)&&!v.trim()))return json({error:'Complete your company and billing details.'},400);customer[k]=v.trim();}
 if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(customer.email)||d.accepted!==true||d.company_fax)return json({error:'Check your email and acknowledge the purchase details.'},400);
 const tax=config.tax[customer.country];if(!tax||!Number.isInteger(tax.bps)||tax.bps<0||tax.bps>10000||typeof tax.label!=='string'||!tax.label||(tax.bps>0&&!env.INVOICE_VAT_NUMBER))return json({error:'Please contact BT38 to confirm billing for this country before purchasing.'},400);
 const key='checkout/orders/'+d.id+'.json';let order=await checkoutGet(env,key);const tokenHash=await digest(d.token),detailsHash=await digest(JSON.stringify({customer,product:d.product,enquiry_id:d.enquiry_id||'',quote_id:d.quote_id||'',referral_code:d.referral_code||''}));
 if(order&&(order.owner!==uid||order.token_hash!==tokenHash||order.details_hash!==detailsHash))return json({error:'This checkout reference is already in use.'},409);
 if(!order){const lastKey='checkout/limits/'+await digest(customer.email.toLowerCase()),last=await env.BUCKET.get(lastKey);if(last&&Date.now()-Number(await last.text())<60000)return json({error:'Please wait a minute before creating another checkout.'},429);
 let referral=offer.enquiry?.referral?{code:offer.enquiry.referral.code,owner:offer.enquiry.referral.owner,terms:{...offer.enquiry.referral,version:offer.enquiry.referral.terms_version}}:null;if(d.referral_code&&!referral){const resolved=await resolveReferral(env,d.referral_code);if(!resolved||resolved.partner.email.toLowerCase()===customer.email.toLowerCase())return json({error:'Referral code unavailable for this purchase.'},400);referral={code:resolved.partner.code,owner:resolved.partner.owner,terms:resolved.partner.terms};}
 order={id:d.id,owner:uid,token_hash:tokenHash,details_hash:detailsHash,product:offer.product,amount:offer.product.amount,enquiry_id:offer.enquiry?.id||null,quote_id:offer.quote?.id||null,hosting_acknowledgement:offer.product.self_hosted?{version:'hosting-v1',text:HOSTING_TERMS,accepted_at:new Date().toISOString()}:null,customer,tax_bps:tax.bps,tax_label:tax.label,seller:{name:env.INVOICE_SELLER_NAME,address:env.INVOICE_SELLER_ADDRESS,email:env.INVOICE_CONTACT_EMAIL,company_number:env.INVOICE_COMPANY_NUMBER,vat_number:env.INVOICE_VAT_NUMBER||''},referral,created_at:new Date().toISOString(),accepted_at:new Date().toISOString(),state:'creating'};
 const added=await env.BUCKET.put(key,JSON.stringify(order),{onlyIf:{etagDoesNotMatch:'*'}});if(added===null)return json({error:'Checkout is being created. Try again shortly.'},409);await env.BUCKET.put(lastKey,String(Date.now()));}
 if(!order.provider_id){try{const payment=await merchant(env,'orders','POST',{amount:order.amount,currency:'GBP',description:order.product.name,capture_mode:'automatic',customer:{email:customer.email,full_name:customer.name},merchant_order_data:{reference:order.id},redirect_url:url.origin+'/billing?id='+order.id+'&token='+d.token},'checkout-'+order.id);
 const target=new URL(payment.checkout_url),allowed=env.REVOLUT_SANDBOX==='true'?'sandbox-checkout.revolut.com':'checkout.revolut.com';if(!/^[a-f0-9-]{36}$/.test(payment.id||'')||target.protocol!=='https:'||target.hostname!==allowed)throw Error();order.provider_id=payment.id;order.checkout_url=target.href;order.state='pending';await env.BUCKET.put(key,JSON.stringify(order));await env.BUCKET.put('checkout/provider/'+payment.id+'.json',JSON.stringify({id:order.id}));}catch{return json({error:'Unable to start payment. No payment has been confirmed. Retry with the same details.'},502);}}
 await env.BUCKET.put('customers/orders/'+await digest(uid)+'/'+order.id+'.json',JSON.stringify({id:order.id}));
 const recordKey='records/enquiry/'+(order.enquiry_id||order.id)+'.json';const existingRecord=await checkoutGet(env,recordKey);if(!existingRecord){const t=order.referral?.terms;await env.BUCKET.put(recordKey,JSON.stringify({id:order.id,kind:'enquiry',customer_owner:order.owner,reference:'BT38-E-'+order.id.replaceAll('-','').slice(0,12).toUpperCase(),date:order.created_at,name:customer.name,company:customer.company,email:customer.email,country:customer.country,phone:customer.phone,service:order.product.name,description:order.product.detail,status:'New',assigned:'',notes:'Checkout created; payment status must be verified.',lead_source:'Checkout',notification:'not_configured',...(order.referral?{referral:{code:order.referral.code,owner:order.referral.owner,commission_model:t.commission_model,commission_bps:t.commission_bps,terms_version:t.version,hold_days:t.hold_days,payout_days:t.payout_days}}:{})}),{onlyIf:{etagDoesNotMatch:'*'}});}
 return json({billing_url:'/billing?id='+order.id+'&token='+d.token});}
 if((path==='/api/checkout/status'||path==='/api/checkout/invoice')&&req.method==='GET'){
 const id=url.searchParams.get('id'),token=url.searchParams.get('token'),uid=req.headers.get('oai-authenticated-user-id');if(!/^[a-f0-9-]{36}$/.test(id||''))return json({error:'Checkout not found.'},404);const order=await checkoutGet(env,'checkout/orders/'+id+'.json');if(!order||(order.owner?order.owner!==uid:(!/^[a-f0-9]{64}$/.test(token||'')||order.token_hash!==await digest(token))))return json({error:'Checkout not found.'},404);
 let payment=null,invoice=await checkoutGet(env,'checkout/invoices/'+id+'.json'),pendingEmail=false;
 if(order.provider_id){try{payment=await merchant(env,'orders/'+order.provider_id);if(payment.state==='completed'){try{invoice=await issueInvoice(env,order,payment);}catch{pendingEmail=true;invoice=await checkoutGet(env,'checkout/invoices/'+id+'.json');if(!invoice)return json({error:'Payment details could not be matched to this purchase. Please contact BT38.'},409);}}}catch{return json({error:'Payment status could not be verified. Please try again.'},503);}}
 if(path.endsWith('/invoice')){if(!invoice)return json({error:'A paid invoice is available only after verified payment.'},409);return new Response(invoiceHtml(invoice),{headers:{...HEADERS,'Referrer-Policy':'no-referrer','Content-Type':'text/html; charset=utf-8'}});}
 const state=payment?.state|| (invoice?'completed':order.state);return json({product:order.product,amount:order.amount,tax_bps:order.tax_bps,tax_label:order.tax_label,company:order.customer.company,email:order.customer.email,state,checkout_url:['pending','new'].includes(state)?order.checkout_url:null,invoice_ready:!!invoice,invoice_email:invoice?.email_state|| (pendingEmail?'pending':null)});}
 return json({error:'Not found.'},404);
}

const CHECKOUT_SCRIPT="(()=>{'use strict';\nconst $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c])),money=p=>new Intl.NumberFormat('en-GB',{style:'currency',currency:'GBP'}).format(p/100),params=new URLSearchParams(location.search);\nasync function api(path,method='GET',data){const r=await fetch(path,{method,headers:{'Content-Type':'application/json'},...(data?{body:JSON.stringify(data)}:{})});const d=await r.json();if(!r.ok)throw Object.assign(Error(d.error||'Unable to complete checkout.'),{status:r.status});return d;}\nasync function start(){const f=$('#checkout-form');if(!f)return;let customer;try{customer=await api('/api/customer/account');}catch(err){if(err.status!==401)throw err;location.assign('/signup?returnTo='+encodeURIComponent(location.pathname+location.search));return;}if(!customer.profile){location.assign('/signup?returnTo='+encodeURIComponent(location.pathname+location.search));return;}for(const [key,value] of Object.entries(customer.profile)){if(f.elements[key]&&typeof value==='string')f.elements[key].value=value;}const c=await api('/api/checkout/config'),key=params.get('product'),product=key==='quote'?(await api('/api/sales/checkout-offer?product=quote&enquiry='+encodeURIComponent(params.get('enquiry')||'')+'&quote='+encodeURIComponent(params.get('quote')||''))).product:Object.hasOwn(c.products,key)?c.products[key]:null;if(!product){$('#checkout-availability').textContent='Select a package from the Price page to continue.';return;}$('#checkout-product').textContent=product.name;$('#checkout-price').textContent=money(product.amount)+(key==='support'?' for one month':' one-off starting package');$('#checkout-detail').textContent=product.detail;$('#checkout-availability').textContent=c.ready?'Your final billing total is shown before payment. Prices include any tax configured for your billing country.':c.message;const button=f.querySelector('button');button.disabled=!c.ready;const id=crypto.randomUUID(),token=Array.from(crypto.getRandomValues(new Uint8Array(32)),b=>b.toString(16).padStart(2,'0')).join('');\nf.onsubmit=async e=>{e.preventDefault();button.disabled=true;$('#checkout-result').textContent='Preparing your billing page…';const data=Object.fromEntries(new FormData(f));data.country=data.country.trim().toUpperCase();try{const d=await api('/api/checkout/create','POST',{...data,id,token,product:key,enquiry_id:params.get('enquiry')||undefined,quote_id:params.get('quote')||undefined,hosting_acknowledged:f.elements.hosting_acknowledged?.checked===true,accepted:f.elements.accepted.checked,referral_code:params.get('ref')||''});location.assign(d.billing_url);}catch(err){$('#checkout-result').textContent=err.message;button.disabled=false;}};}\nasync function billing(){const host=$('#billing-summary');if(!host)return;const query=new URLSearchParams({id:params.get('id')||'',token:params.get('token')||''});try{const d=await api('/api/checkout/status?'+query);host.innerHTML='<h2>'+esc(d.product.name)+'</h2><p>'+esc(d.product.detail)+'</p><p>Company: '+esc(d.company)+'<br>Invoice email: '+esc(d.email)+'</p><p class=\"price\">'+money(d.amount)+'</p><p>'+esc(d.tax_label)+'</p>'+(d.state==='completed'?'<h3>Payment confirmed</h3><p>Your paid invoice '+(d.invoice_email==='sent'?'has been emailed to your invoice address.':'is available in your customer account. You can view it below.')+'</p><a class=\"btn primary\" target=\"_blank\" rel=\"noreferrer\" href=\"/api/checkout/invoice?'+esc(query)+'\">View paid invoice ↗</a>':d.checkout_url?'<p>No payment has been confirmed yet.</p><a class=\"btn primary\" rel=\"noreferrer\" href=\"'+esc(d.checkout_url)+'\">Pay '+money(d.amount)+' securely ↗</a>':'<p>Payment status: '+esc(d.state)+'. Contact BT38 if you need assistance.</p>')+'<p><button class=\"btn\" id=\"check-payment\">Refresh payment status</button></p>';$('#check-payment').onclick=billing;}catch(e){host.textContent=e.message;}}\nstart().catch(e=>{const el=$('#checkout-availability');if(el)el.textContent=e.message;});billing();})();";

import {NeonRecordStore} from './neon-record-store.js';

import {customerApi,partnerProfileApi} from "./customer-accounts.js";
const CUSTOMER_SCRIPT="(()=>{'use strict';\nconst $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c])),money=p=>new Intl.NumberFormat('en-GB',{style:'currency',currency:'GBP'}).format(p/100),params=new URLSearchParams(location.search);\nasync function api(path,method='GET',data){const r=await fetch(path,{method,headers:{'Content-Type':'application/json'},...(data?{body:JSON.stringify(data)}:{})});const d=await r.json();if(!r.ok)throw Object.assign(Error(d.error||'Please try again.'),{status:r.status,signup:d.signup});return d;}\nfunction signin(host,partner=false){const next=location.pathname+location.search;host.innerHTML='<h3>'+(partner?'Your partner account':'Your customer account')+'</h3><p>Continue securely with Google to create or access your BT38 account. Your company details and records remain private.</p><a class=\"btn primary\" target=\"_top\" href=\"/auth/google?returnTo='+encodeURIComponent(next)+'\">Continue with Google \u2197</a>';}\nconst field=(name,label,value='',required=false,type='text')=>'<label class=\"field\" for=\"p-'+name+'\">'+label+(required?' *':'')+'<input id=\"p-'+name+'\" name=\"'+name+'\" type=\"'+type+'\" maxlength=\"500\" value=\"'+esc(value)+'\" '+(required?'required':'')+'></label>';\nfunction bindSave(form,path,result,after){form.onsubmit=async e=>{e.preventDefault();const b=form.querySelector('button');b.disabled=true;result.textContent='Saving\u2026';try{const d=await api(path,'POST',Object.fromEntries(new FormData(form)));result.textContent='Saved.';if(after)await after(d);}catch(err){result.textContent=err.message;}finally{b.disabled=false;}};}\nasync function customer(){const host=$('#customer-area');if(!host)return;let data;try{data=await api('/api/customer/account');}catch(e){if(e.status===401){signin(host);return;}throw e;}const profile=data.profile;\nif(location.pathname==='/signup'){\nhost.innerHTML='<h2>'+ (profile?'Your company details':'Create your customer account')+'</h2><p>Signed in as '+esc(data.email)+'. We use this account to keep your purchases, onboarding and support together.</p><form id=\"profile-form\"><div class=\"fields\">'+[['company','Business / company name',true],['name','Contact name',true],['phone','Telephone',false],['address','Billing address',false],['city','Town / city',false],['postcode','Postcode / ZIP',false],['country','Country (two-letter code, e.g. GB)',true],['company_number','Company registration number',false],['vat_number','VAT / tax number',false]].map(([k,l,r])=>field(k,l,profile?.[k]||'',r)).join('')+'</div><p class=\"muted\">Your details are used to manage your customer account and purchases. <a href=\"/privacy\">Privacy information \u2197</a></p><button class=\"btn primary\">'+(profile?'Save company details':'Create account')+' \u2197</button><p id=\"profile-result\" role=\"status\"></p></form>';\nbindSave($('#profile-form'),'/api/customer/account',$('#profile-result'),()=>{const requested=params.get('returnTo'),next=requested&&/^\\/(?!\\/)/.test(requested)?requested:'/account';location.assign(next);});return;}\nif(!profile){host.innerHTML='<h2>Complete your company profile</h2><p>Add your business details to open your customer workspace.</p><a class=\"btn primary\" href=\"/signup\">Complete sign up \u2197</a>';return;}\nif(location.pathname==='/account'){\nhost.innerHTML='<div class=\"section-head\"><div><div class=\"eyebrow\">Customer workspace</div><h2>'+esc(profile.company)+'</h2><p>'+esc(profile.name)+' \u00b7 '+esc(data.email)+'</p></div><a class=\"btn\" href=\"/signup\">Edit company details</a></div><div class=\"cards\"><article class=\"card\"><span class=\"tag\">Your delivery</span><h3>'+esc(data.onboarding?.stage||'Onboarding ready to start')+'</h3><p>Tell us your brand, platforms and operating requirements.</p><a class=\"btn primary\" href=\"/account/onboarding\">Open onboarding \u2197</a></article><article class=\"card\"><span class=\"tag\">Purchases & invoices</span><h3>Billing in one place</h3><p>Review your orders, continue payment and view paid invoices.</p><a class=\"btn\" href=\"/account/billing\">Open billing \u2197</a></article><article class=\"card\"><span class=\"tag\">Help with your system</span><h3>Contact BT38 support</h3><p>Raise an issue and follow the conversation from your account.</p><a class=\"btn\" href=\"/account/support\">Open support \u2197</a></article></div>';return;}\nif(location.pathname==='/account/onboarding'){\nconst o=data.onboarding||{};host.innerHTML='<h2>Your brand. Your requirements.</h2><p class=\"notice\">Delivery stage: '+esc(o.stage||'Not started')+'</p><form id=\"onboarding-form\"><div class=\"fields\">'+[['brand_name','Name to brand the system under',true],['brand_colours','Brand colours',false],['website','Business website',false],['platforms','Marketplaces and web stores to connect',false],['shipping','Shipping providers',false],['warehouses','Warehouse locations',false]].map(([k,l,r])=>field(k,l,o[k]||'',r)).join('')+'<label class=\"field full\">What should the system help you do?<textarea name=\"requirements\" maxlength=\"6000\">'+esc(o.requirements||'')+'</textarea></label></div><p class=\"muted\">Share business requirements only. Credentials and payment details are collected through their secure provider connections.</p><button class=\"btn primary\">Save onboarding details \u2197</button><p id=\"onboarding-result\" role=\"status\"></p></form>';bindSave($('#onboarding-form'),'/api/customer/onboarding',$('#onboarding-result'));return;}\nif(location.pathname==='/account/billing'){\nconst b=await api('/api/customer/billing');host.innerHTML='<div class=\"section-head\"><div><h2>Your purchases & invoices</h2><p>Company: '+esc(profile.company)+'</p></div><a class=\"btn primary\" href=\"/checkout?product=system\">System checkout \u2197</a></div>'+(b.orders.length?b.orders.map(o=>'<article class=\"card\" style=\"margin-bottom:18px\"><span class=\"tag\">'+esc(o.status)+'</span><h3>'+esc(o.product.name)+'</h3><p>'+money(o.amount)+' \u00b7 '+esc(new Date(o.date).toLocaleDateString('en-GB'))+'</p><div class=\"actions\"><a class=\"btn\" href=\"/billing?id='+esc(o.id)+'\">View order \u2197</a>'+(o.invoice_number?'<a class=\"btn primary\" target=\"_blank\" rel=\"noreferrer\" href=\"/api/customer/invoices/'+esc(o.id)+'\">View invoice \u2197</a>':'')+'</div></article>').join(''):'<div class=\"notice\"><h3>Your purchases will appear here</h3><p>Choose your system from the Price page. Paid invoices are added after payment is verified.</p><a class=\"btn\" href=\"/integrations#pricing\">View Price \u2197</a></div>')+'<p class=\"muted\">Payment details are entered directly with Revolut. Your BT38 account holds order and invoice records.</p>';return;}\nif(location.pathname==='/account/support'){\nconst d=await api('/api/customer/support');host.innerHTML='<div class=\"section-head\"><div><h2>Support for your system</h2><p>Raise an issue and keep replies together here.</p></div><a class=\"btn primary\" href=\"/checkout?product=support\">One month of support \u00b7 \u00a399 \u2197</a></div><p class=\"notice\">The starting system includes three months of support for faults or issues from handover. Further support is \u00a399 for one month, purchased as needed with no automatic renewal. New features and bespoke work are priced separately.</p><form id=\"support-form\"><h3>Send a support request</h3>'+field('subject','What do you need help with?','',true)+'<label class=\"field\">Describe the issue<textarea name=\"message\" maxlength=\"6000\" required></textarea></label><p class=\"muted\">Include the page, action and error you saw. Keep passwords and bank/card details out of messages.</p><button class=\"btn primary\">Send support request \u2197</button><p id=\"support-result\" role=\"status\"></p></form><div class=\"divider\"></div><h3>Your requests</h3>'+(d.tickets.length?d.tickets.map(t=>'<article class=\"card\" style=\"margin-bottom:18px\"><span class=\"tag\">'+esc(t.status)+'</span><h3>'+esc(t.subject)+'</h3>'+t.messages.map(m=>'<p><strong>'+esc(m.role)+'</strong> \u00b7 '+esc(new Date(m.date).toLocaleString('en-GB'))+'<br>'+esc(m.message).replace(/\\n/g,'<br>')+'</p>').join('')+'<form class=\"ticket-reply\" data-id=\"'+esc(t.id)+'\"><label class=\"field\">Your reply<textarea name=\"message\" required maxlength=\"6000\"></textarea></label><button class=\"btn\">Send reply</button><p class=\"reply-result\" role=\"status\"></p></form></article>').join(''):'<p class=\"muted\">No support requests yet.</p>');\nconst f=$('#support-form');f.onsubmit=async e=>{e.preventDefault();const b=f.querySelector('button');b.disabled=true;try{await api('/api/customer/support','POST',{...Object.fromEntries(new FormData(f)),id:crypto.randomUUID()});await customer();}catch(err){$('#support-result').textContent=err.message;b.disabled=false;}};\ndocument.querySelectorAll('.ticket-reply').forEach(f=>bindSave(f,'/api/customer/support/reply',f.querySelector('.reply-result'),customer));document.querySelectorAll('.ticket-reply').forEach(f=>{f.insertAdjacentHTML('afterbegin','<input type=\"hidden\" name=\"id\" value=\"'+esc(f.dataset.id)+'\">');});}\n}\nasync function admin(){const host=$('#customer-admin');if(!host)return;try{const d=await api('/api/customer/admin/overview');host.innerHTML='<h2>Customers & support</h2><p>'+d.customers.length+' customer profiles</p>'+d.customers.map(c=>'<details class=\"card\" style=\"margin-bottom:12px\"><summary>'+esc(c.company)+' \u00b7 '+esc(c.email)+'</summary><form class=\"delivery-form\"><input type=\"hidden\" name=\"owner\" value=\"'+esc(c.owner)+'\"><label class=\"field\">Delivery stage<select name=\"stage\">'+['Requirements received','In review','Configuration','Testing','Ready for handover','Live'].map(x=>'<option>'+x+'</option>').join('')+'</select></label>'+field('handover_at','Handover date (when agreed)','','', 'date')+'<button class=\"btn\">Update delivery</button><p role=\"status\"></p></form></details>').join('')+'<h3>Support requests</h3>'+(d.tickets.length?d.tickets.map(t=>'<article class=\"card\" style=\"margin-bottom:16px\"><span class=\"tag\">'+esc(t.status)+'</span><h3>'+esc(t.company)+' \u00b7 '+esc(t.subject)+'</h3>'+t.messages.map(m=>'<p><strong>'+esc(m.role)+'</strong><br>'+esc(m.message)+'</p>').join('')+'<form class=\"admin-reply\"><input type=\"hidden\" name=\"key\" value=\"'+esc(t.key)+'\"><label class=\"field\">BT38 reply<textarea name=\"message\" maxlength=\"6000\" required></textarea></label><label class=\"field\">Status<select name=\"status\"><option>Open</option><option>Awaiting customer</option><option>Resolved</option></select></label><button class=\"btn primary\">Send reply</button><p role=\"status\"></p></form></article>').join(''):'<p>No support requests.</p>');document.querySelectorAll('.delivery-form').forEach(f=>bindSave(f,'/api/customer/admin/onboarding',f.querySelector('[role=status]')));document.querySelectorAll('.admin-reply').forEach(f=>bindSave(f,'/api/customer/admin/support',f.querySelector('[role=status]'),admin));}catch(e){host.textContent=e.message;}}\ncustomer().catch(e=>{const h=$('#customer-area');if(h)h.textContent=e.message;});admin();})();\n";

import {googleAuthApi,googleIdentity} from "./google-auth.js";
const GOOGLE_BROWSER_SCRIPT="(()=>{'use strict';async function start(){const host=document.getElementById('google-signin');if(!host)return;const result=document.getElementById('google-result');const returnTo=new URLSearchParams(location.search).get('returnTo')||'/account';try{const r=await fetch('/api/auth/google/start',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({returnTo})}),config=await r.json();if(!r.ok)throw Error(config.error||'Google sign-in is unavailable.');await new Promise((resolve,reject)=>{const s=document.createElement('script');s.src='https://accounts.google.com/gsi/client';s.async=true;s.onload=resolve;s.onerror=()=>reject(Error('Google sign-in could not load. Please try again.'));document.head.appendChild(s);});google.accounts.id.initialize({client_id:config.client_id,nonce:config.nonce,auto_select:false,use_fedcm_for_button:true,callback:async response=>{result.textContent='Signing you in\u2026';try{const r=await fetch('/api/auth/google/complete',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({credential:response.credential})}),d=await r.json();if(!r.ok)throw Error(d.error);location.assign(d.redirect);}catch(e){result.textContent=e.message;}}});google.accounts.id.renderButton(host,{type:'standard',theme:'outline',size:'large',text:'continue_with',shape:'rectangular'});result.textContent='Use your Gmail or verified Google Workspace account.';}catch(e){result.textContent=e.message;}}start();document.querySelectorAll('[data-google-logout]').forEach(b=>b.onclick=async()=>{const r=await fetch('/api/auth/logout',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});if(r.ok)location.assign('/login');});})();\n";
